s = sys.stdin.read().split()[0]
n = len(s)
count = 0
for i in range(n):
    for j in range(i + 1, n):
        t = s[i:j + 1]
        if t[0] == '1' and t[-1] == '1' and all(c == '0' for c in t[1:-1]):
            count += 1
print(count)

